# Kaggle selects the last top-level callable in a submission file.
def agent(obs):
    step = obs.get("step", obs.get("day", 0) * 24 + obs.get("hour", 0))
    if 0 <= step < len(_ACTIONS):
        return _ACTIONS[step]
    return {"farmer": ["PASS"], "hands": [], "market": []}

